<?php require_once __DIR__.'/config/config.php';require_login();$page_title='Explore Members';$users=$conn->query('SELECT id,username,display_name,bio,avatar_url FROM users ORDER BY created_at DESC LIMIT 100');require __DIR__.'/includes/header.php';?><div class="page-heading"><p class="eyebrow">MEET THE COMMUNITY</p><h1>Explore Members ♡</h1></div><div class="members-grid"><?php while($u=$users->fetch_assoc()):?><a class="card member-card" href="profile.php?u=<?=e(rawurlencode($u['username']))?>"><div class="member-avatar"><?=avatar_html($u['avatar_url'],$u['display_name'])?></div><strong><?=e($u['display_name'])?></strong><small>@<?=e($u['username'])?></small><p><?=e($u['bio']?:'RPWVERSE member')?></p></a><?php endwhile;?></div><?php require __DIR__.'/includes/footer.php';?>